create function pg_temp.assert_true(value boolean,label text) returns text language plpgsql as $$ begin
 if value is distinct from true then raise exception 'FAIL: %',label; end if; return label; end; $$;
create function pg_temp.expect_error(statement text,expected_state text,label text) returns text language plpgsql as $$ begin
 begin execute statement; exception when others then if sqlstate=expected_state then return label; end if; raise exception 'FAIL: %, expected %, got %',label,expected_state,sqlstate; end;
 raise exception 'FAIL: %, unexpectedly succeeded',label; end; $$;
insert into auth.users(id) values('80000000-0000-0000-0000-000000000001'),('80000000-0000-0000-0000-000000000002');
set local role service_role;
select public.auth_signup('80000000-0000-0000-0000-000000000001','legacy_a@invalid','legacy_a','리더','Legacy A',null,repeat('a',64),repeat('b',64));
select public.auth_signup('80000000-0000-0000-0000-000000000002','legacy_b@invalid','legacy_b','리더','Legacy B',null,repeat('c',64),repeat('d',64));
insert into public.songs(id,band_id,created_by,title,artist,vocal_type) select 'legacy_a1',band_id,user_id,'First','Artist','female' from public.band_memberships where user_id='80000000-0000-0000-0000-000000000001';
insert into public.songs(id,band_id,created_by,title,artist,vocal_type) select 'legacy_a2',band_id,user_id,'Second','Artist','female' from public.band_memberships where user_id='80000000-0000-0000-0000-000000000001';
insert into public.songs(id,band_id,created_by,title,artist,vocal_type) select 'legacy_b1',band_id,user_id,'Foreign','Artist','female' from public.band_memberships where user_id='80000000-0000-0000-0000-000000000002';
insert into private.legacy_song_votes(song_id,likes,dislikes,source_sha256) values('legacy_a1',7,2,repeat('a',64)),('legacy_a2',4,0,repeat('a',64)),('legacy_b1',100,0,repeat('b',64));
insert into private.legacy_song_votes(song_id,likes,dislikes,source_sha256) values('legacy_a1',7,2,repeat('a',64)) on conflict(song_id) do update set likes=excluded.likes,dislikes=excluded.dislikes,source_sha256=excluded.source_sha256;
select pg_temp.assert_true((select likes=7 and dislikes=2 from private.legacy_song_votes where song_id='legacy_a1'),'repeat import replaces baseline without doubling') as assertion;
reset role;
set local request.jwt.claim.sub='80000000-0000-0000-0000-000000000001';
set local role authenticated;
select pg_temp.assert_true((select likes=7 and dislikes=2 from public.get_song_stats(array['legacy_a1'])),'stats include imported likes and dislikes') as assertion;
select pg_temp.assert_true((select count(*)=0 from public.get_my_votes(array['legacy_a1'])),'legacy votes do not impersonate authenticated account selections') as assertion;
select public.toggle_vote('legacy_a1',1::smallint);
select pg_temp.assert_true((select likes=8 and dislikes=2 from public.get_song_stats(array['legacy_a1'])),'new app like adds to baseline') as assertion;
select public.toggle_vote('legacy_a1',1::smallint);
select pg_temp.assert_true((select likes=7 and dislikes=2 from public.get_song_stats(array['legacy_a1'])),'cancelling own like preserves original baseline') as assertion;
select public.toggle_vote('legacy_a1',(-1)::smallint);
select pg_temp.assert_true((select likes=7 and dislikes=3 from public.get_song_stats(array['legacy_a1'])),'new app dislike adds independently') as assertion;
select pg_temp.assert_true(public.list_song_catalog()->'songs'->0->>'id'='legacy_a1','popularity ordering includes legacy likes') as assertion;
select pg_temp.assert_true((public.list_song_catalog(p_sort=>'net')->'songs'->0->>'id')='legacy_a1','net ranking includes baseline likes and dislikes') as assertion;
select pg_temp.assert_true((public.list_song_catalog()->>'legacy_vote_total')::int=13,'legacy total is scoped to current band') as assertion;
select pg_temp.assert_true((select count(*)=0 from public.get_song_stats(array['legacy_b1'])),'foreign baseline never appears in stats') as assertion;
select pg_temp.expect_error('select * from private.legacy_song_votes','42501','members cannot read private baseline table') as assertion;
select pg_temp.expect_error($s$update private.legacy_song_votes set likes=999 where song_id='legacy_a1'$s$,'42501','members cannot alter imported baseline') as assertion;
update public.songs set is_confirmed=true where id='legacy_a1';
select pg_temp.assert_true(public.list_song_catalog()->'songs'->0->>'id'='legacy_a2','confirmed legacy winner is excluded from wish popularity') as assertion;
select pg_temp.assert_true((public.list_song_catalog(p_confirmed=>true)->'songs'->0->>'likes')::int=7,'confirmed catalog keeps imported count') as assertion;
reset role;
set local role anon;
select pg_temp.expect_error($s$select public.get_song_stats(array['legacy_a1'])$s$,'42501','anonymous visitor cannot access aggregate baseline') as assertion;
reset role;
